#!/usr/bin/env bash
set -uo pipefail

OUT="posterx_posters"
mkdir -p "$OUT"

download() {
  local name="$1"; local url="$2"
  echo "Downloading $name ..."
  curl -fsSL -A "Mozilla/5.0" "$url" -o "$OUT/$name" || echo "FAILED: $name"
}

